const runs=new Map();
self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
self.addEventListener('message',e=>{if(e.data?.type==='configure'&&e.source?.id){runs.set(e.source.id,{tasks:e.data.tasks,custom:e.data.custom,meta:e.data.meta||{versions:{},idempotency:{}}});e.ports[0]?.postMessage({ok:true,version:2})}});
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(u.origin===self.location.origin&&u.pathname.startsWith('/api/runtime/'))e.respondWith(handle(e.request,runs.get(e.clientId)))});
async function handle(request,c){
 const json=(body,status=200,extra={})=>new Response(status===204?null:JSON.stringify(body,null,2),{status,headers:{'Content-Type':'application/json; charset=utf-8','X-Practice-State':encodeURIComponent(JSON.stringify(c?.tasks||[])),'X-Practice-Meta':encodeURIComponent(JSON.stringify(c?.meta||{})),'X-Practice-Mode':'local-simulation',...extra}});
 if(!c)return json({error:'sandbox_not_ready'},503);
 c.meta.versions||={};c.meta.idempotency||={};
 const u=new URL(request.url),path=decodeURIComponent(u.pathname.slice('/api/runtime'.length)).replace(/\/$/,'')||'/',method=request.method;
 let body=null;if(!['GET','HEAD'].includes(method)){const raw=await request.text();if(raw){try{body=JSON.parse(raw)}catch{return json({error:'invalid_json'},400)}}}
 if(path==='/admin/stats'){const auth=request.headers.get('Authorization');if(!auth)return json({error:'unauthorized'},401,{'WWW-Authenticate':'Bearer'});if(auth!=='Bearer practice-admin')return json({error:'forbidden'},403);if(method!=='GET')return json({error:'method_not_allowed'},405);return json({total:c.tasks.length,completed:c.tasks.filter(t=>t.completed).length})}
 const match=path.match(/^\/tasks(?:\/(\d+))?$/);
 if(!match){const custom=c.custom.find(e=>e.method===method&&matchPath(e.path,path));if(!custom)return json({error:'not_found'},404);if(custom.required?.length&&(!body||typeof body!=='object'||Array.isArray(body)||custom.required.some(k=>!Object.prototype.hasOwnProperty.call(body,k)||body[k]===null||body[k]==='')))return json({error:'validation_error',message:'Обязательные поля: '+custom.required.join(', ')},422);return json(custom.response,custom.status)}
 const id=match[1]?Number(match[1]):null,task=c.tasks.find(t=>t.id===id),etag=()=>`"task-${id}-v${c.meta.versions[id]||1}"`;
 if(method==='GET'&&id===null){let items=[...c.tasks];const q=u.searchParams,completed=q.get('completed'),sort=q.get('sort');if(completed!==null&&!['true','false'].includes(completed))return json({error:'invalid_query'},400);if(completed!==null)items=items.filter(t=>t.completed===(completed==='true'));if(sort){if(!['id','-id','title','-title'].includes(sort))return json({error:'invalid_query'},400);const k=sort.replace('-','');items.sort((a,b)=>(k==='id'?a.id-b.id:a.title.localeCompare(b.title))*(sort[0]==='-'?-1:1))}const total=items.length;if(q.has('page')||q.has('limit')){const page=Number(q.get('page')??1),limit=Number(q.get('limit')??10);if(!Number.isInteger(page)||page<1||!Number.isInteger(limit)||limit<1||limit>100)return json({error:'invalid_query'},400);return json({items:items.slice((page-1)*limit,page*limit),total,page,limit})}return json({items,total})}
 if(method==='POST'&&id===null){if(!body||typeof body.title!=='string'||!body.title.trim()||(body.completed!==undefined&&typeof body.completed!=='boolean'))return json({error:'validation_error',message:'title — непустая строка; completed — boolean.'},422);const payload={title:body.title.trim(),completed:body.completed??false},fingerprint=JSON.stringify(payload),key=request.headers.get('Idempotency-Key'),record=key&&Object.prototype.hasOwnProperty.call(c.meta.idempotency,key)?c.meta.idempotency[key]:null;if(record){if(record.fingerprint!==fingerprint)return json({error:'idempotency_conflict'},409);return json(record.item,201,{'Idempotency-Replayed':'true'})}const nextId=Math.max(c.meta.nextId||1,1+Math.max(0,...c.tasks.map(t=>t.id)));c.meta.nextId=nextId+1;const item={id:nextId,...payload};c.tasks.push(item);c.meta.versions[nextId]=1;if(key)Object.defineProperty(c.meta.idempotency,key,{value:{fingerprint,item:{...item}},enumerable:true,writable:true,configurable:true});return json(item,201,{'Idempotency-Replayed':'false'})}
 if(id!==null&&!task)return json({error:'not_found'},404);
 if(method==='GET'&&task)return json(task,200,{ETag:etag()});
 if(task&&['PUT','PATCH','DELETE'].includes(method)){const conditional=request.headers.get('If-Match');if(conditional&&conditional!=='*'&&!conditional.split(',').map(x=>x.trim()).includes(etag()))return json({error:'precondition_failed'},412,{ETag:etag()});if(method==='DELETE'){c.tasks=c.tasks.filter(t=>t.id!==id);return json(null,204)}if(!body||typeof body!=='object'||Array.isArray(body)||(method==='PUT'||'title'in body)&&(typeof body.title!=='string'||!body.title.trim())||(method==='PUT'||'completed'in body)&&typeof body.completed!=='boolean')return json({error:'validation_error'},422);if(body.title!==undefined)task.title=body.title.trim();if(body.completed!==undefined)task.completed=body.completed;c.meta.versions[id]=(c.meta.versions[id]||1)+1;return json(task,200,{ETag:etag()})}
 return json({error:'method_not_allowed'},405);
}
function matchPath(template,path){const a=template.split('/'),b=path.split('/');return a.length===b.length&&a.every((s,i)=>/^\{[a-zA-Z_][a-zA-Z0-9_]*\}$/.test(s)?!!b[i]:s===b[i])}
